#include <windows.h>
#include <cassert>
#include <fstream>
#include <string>
#include "../deps/json/json.hpp"
using json=nlohmann::json;
#include "../native/monitor_frame_output.h"
int main(int argc,char**argv){assert(argc==2);using namespace ymcc::monitorframe;json checks=json::array();auto check=[&](const char*name,bool ok){checks.push_back({{"name",name},{"ok",ok}});};const uint64_t n=1700000000000ULL;
 Output hw;hw.bind(77,99);hw.hardware(n/1000,120,88,20,30,"game",n+800,8.3,3000);const auto first=hw.packet(n+800);auto wait=hw.packet(n+3100);check("hardware FPS stays valid until next normal 3-second poll",!wait.is_null()&&wait["fps"]==120&&wait["fpsValidUntil"]==n+5000);check("waiting never appends frame samples",wait["frameTimes"]==first["frameTimes"]&&wait["frameTimeTs"]==n);
 hw.hardware(n/1000+3,121,87,20,30,"game",n+3800,8.1,3000);auto next=hw.packet(n+3800);check("normal 3-second producer interval keeps two true observations",next["frameTimes"]==json::array({8.3,8.1})&&next["frameTimeValidUntil"]==n+8000);
 hw.hardware(n/1000+3,121,87,20,30,"game",n+4500,8.1,3000);auto repeated=hw.packet(n+4500);check("same producer poll does not append or renew FPS/frame proofs",repeated["frameTimes"]==next["frameTimes"]&&repeated["fpsValidUntil"]==next["fpsValidUntil"]&&repeated["frameTimeValidUntil"]==next["frameTimeValidUntil"]);
 check("producer cache expires at its own absolute deadline",hw.packet(n+8000).is_null());
 Output missing;missing.bind(77,99);missing.hardware(n/1000,120,88,20,30,"game",n+800,8.3,1000);missing.hardware(n/1000+2,120,87,20,30,"game",n+2800,-1,3000);auto mismatch=missing.packet(n+2800);check("missing frame plus period change never extends previous frame proof",mismatch["frameTimeValidUntil"]==n+5000&&mismatch["frameTimePollPeriodMs"]==1000);auto frameExpired=missing.packet(n+5000);check("old frame expires while a newer FPS packet remains valid",!frameExpired.is_null()&&!frameExpired.contains("frameTimes"));
 Output fast;fast.bind(77,99);fast.observeRtss({true,8.3,120,n+100});fast.observeRtss({true,8.2,120,n+200});auto rtss=fast.packet(n+200);check("RTSS carries the configured five-second absence deadline",rtss["fpsValidUntil"]==n+5200&&rtss["frameTimeValidUntil"]==n+5200&&rtss["fpsPollPeriodMs"]==0&&rtss["frameTimePollPeriodMs"]==0);check("RTSS frozen cache expires independently",fast.packet(n+5200).is_null());
 Output switcher;switcher.bind(77,99);switcher.hardware(n/1000,120,88,20,30,"game",n+800,8.3,3000);switcher.hardware(n/1000+3,121,87,20,30,"game",n+3800,8.1,3000);switcher.observeRtss({true,7.0,142,n+3900});switcher.observeRtss({true,7.1,141,n+4000});auto rtssPreferred=switcher.packet(n+4000);switcher.hardware(n/1000+6,122,86,20,30,"game",n+6800,8.0,3000);auto hwFallback=switcher.packet(n+9100);check("expired RTSS can return to independently fresh HW samples",rtssPreferred["fpsSource"]=="rtss"&&hwFallback["fpsSource"]=="hwinfo-presented"&&hwFallback["frameTimes"]==json::array({8.3,8.1,8.0}));
 Output zero;zero.bind(77,99);zero.hardware(n/1000,0,0,0,0,"game",n+800,8.3,3000);auto realZero=zero.packet(n+3100);check("real zero remains an actual measurement and has no curve",realZero["fps"]==0&&realZero["fps1"]==0&&!realZero.contains("frameTimes"));zero.bind(77,100);check("PID reuse cannot inherit any cached proof",zero.packet(n+3100).is_null());
 bool ok=true;for(const auto&c:checks)ok=ok&&c["ok"].get<bool>();std::ofstream(argv[1])<<json{{"ok",ok},{"checks",checks},{"packets",{{"hardwareFirst",first},{"hardwareNext",next},{"hardwareWait",wait},{"rtss",rtss},{"missingFrame",mismatch},{"frameExpired",frameExpired},{"zero",realZero}}},{"scope","Actual Output/History with genuine synthetic observation timestamps; no added real hardware reader"}}.dump(2);return ok?0:1;}
